// Permission matrix helpers (generated by engineering-platform frontend-enterprise-management asset)
// Group permissions by domain/resource/action so UI shows a readable matrix
// instead of a long list of raw permission-code checkboxes.
import type { Permission } from '../types/enterprise';

export interface PermissionResource {
  resource: string; // e.g. "User", "Role"
  actions: { action: string; permission: Permission }[];
}

export interface PermissionDomain {
  domain: string; // e.g. "System", "Product"
  resources: PermissionResource[];
}

export function domainOf(code: string): string {
  const parts = code.split(':');
  return parts.length >= 2 ? parts[0] : code;
}

export function resourceOf(code: string): string {
  const parts = code.split(':');
  return parts.length >= 2 ? parts[1] : code;
}

export function actionOf(code: string): string {
  const parts = code.split(':');
  return parts.length >= 3 ? parts[2] : (parts[1] ?? code);
}

/** Action code -> readable label (e.g. assign-role -> "Assign role"). */
export function actionLabel(action: string): string {
  const map: Record<string, string> = {
    read: 'Read',
    create: 'Create',
    update: 'Update',
    disable: 'Disable',
    delete: 'Delete',
    'assign-role': 'Assign role',
    'assign-department': 'Assign department',
    'assign-permission': 'Assign permission',
  };
  return map[action] ?? action;
}

export function resourceLabel(resource: string): string {
  const map: Record<string, string> = {
    user: 'User',
    role: 'Role',
    permission: 'Permission',
    department: 'Department',
    menu: 'Menu',
    dictionary: 'Dictionary',
    'operation-log': 'Operation Log',
    item: 'Item',
  };
  return map[resource] ?? resource;
}

export function domainLabel(domain: string): string {
  const map: Record<string, string> = {
    system: 'System',
    product: 'Product',
  };
  return map[domain] ?? domain;
}

/** Group a flat permission list into domains -> resources -> actions (stable order). */
export function groupPermissions(permissions: Permission[]): PermissionDomain[] {
  const domains = new Map<string, Map<string, Permission[]>>();
  for (const p of [...permissions].sort((a, b) => a.code.localeCompare(b.code))) {
    const d = domainOf(p.code);
    const r = resourceOf(p.code);
    if (!domains.has(d)) {
      domains.set(d, new Map());
    }
    const resources = domains.get(d)!;
    if (!resources.has(r)) {
      resources.set(r, []);
    }
    resources.get(r)!.push(p);
  }
  const result: PermissionDomain[] = [];
  for (const [domain, resources] of domains) {
    const domainEntry: PermissionDomain = { domain, resources: [] };
    for (const [resource, perms] of resources) {
      domainEntry.resources.push({
        resource,
        actions: perms.map((p) => ({ action: actionOf(p.code), permission: p })),
      });
    }
    domainEntry.resources.sort((a, b) => a.resource.localeCompare(b.resource));
    domainEntry.resources.forEach((r) =>
      r.actions.sort((a, b) => a.action.localeCompare(b.action)),
    );
    result.push(domainEntry);
  }
  result.sort((a, b) => a.domain.localeCompare(b.domain));
  return result;
}
